-- Adaptive sprint engine content for all 7 pain points: new exercises, test targets and noise
-- thresholds, one sprint_slots row per template slot, test-to-slot links, and the slot ladders.
-- Spec: docs/superpowers/specs/2026-11-12-adaptive-sprint-engine-design.md (sections 5.1, 5.2, 6, 8a).
-- Re-runnable: exercises insert only when the name is missing; content tables use on conflict do nothing.
-- Ladder rows look exercises up by name, so a missing name fails loudly on the not-null exercise_id.

-- ---------------------------------------------------------------- new exercises
select v.* from (values
  ('Ankle: Standing Knee-to-Wall Rock with Hold', 'mobility', 'mobility_stretch', array['ankles'], 'Full-bodyweight version of the knee-to-wall mobilization. A 5-second end-range pause under load builds on the half-kneeling drill, and weight-bearing dorsiflexion is exactly what the knee-to-wall test measures.', 'B', array['wall'], 2, '10 reps', true, true, 'Face a wall in a split stance and drive your front knee to the wall with the heel down, holding 5 seconds each time.', 'Stand facing a wall with one foot forward, toes a hand''s width from it. Push your front knee toward the wall while keeping the heel flat, and hold the end position for 5 seconds. Come back and repeat. Move your foot back a little as it gets easy. Keep your knee tracking over your middle toes. Then switch feet.'),
  ('Ankle: Single-Leg Balance on Folded Towel, Eyes Closed', 'balance', 'balance', array['ankles'], 'A thickly folded towel gives an unstable surface like a foam pad, so the eyes-closed progression needs no equipment. Balance training is the best-supported treatment for chronic ankle instability.', 'A', array['towel'], 3, '30s', true, true, 'Stand on one foot on a thickly folded towel, close your eyes, and stay still.', 'Fold a bath towel into a thick square on the floor. Stand on it barefoot on one leg with a soft knee and your hands on your hips. Find your balance, then close your eyes. Let your foot make small corrections. If you touch down, open your eyes and start again. Then switch legs.'),
  ('Ankle: Two-Leg Lateral Line Hop', 'balance', 'plyometric', array['ankles'], 'Small two-footed hops over a line share the landing load between both ankles, so the outer-ankle muscles learn to absorb a sideways landing before a single ankle takes it all. It is the bridge from slow eversion strength to single-leg hops for an ankle with a sprain history.', 'B', array['none'], 3, '8 reps', false, true, 'Feet together, hop sideways over a line in small, quiet hops and freeze each landing for a second.', 'Stand with your feet together beside a line on the floor (a crack, tape or a towel edge). Hop a few inches sideways over it, land softly on both feet and hold still for a second. Hop back the same way. Keep the hops small and your knees soft. Don''t let either ankle roll out. Count each landing as one rep.'),
  ('Ankle: Lateral Hop to Stick', 'balance', 'plyometric', array['ankles'], 'Hop-to-stabilization drills train the fast outer-ankle response that resists the inversion sprain, and they carry over directly to the side hop test.', 'B', array[]::text[], 3, '6 reps', true, true, 'Hop sideways off one foot onto the same foot and freeze the landing for 2 seconds.', 'Stand on one leg. Hop about a foot to the side and land on the same foot with a soft knee. Hold the landing still for 2 seconds, then hop back. Keep your knee over your toes and don''t let the ankle roll out. Start with small hops. Then switch legs.'),
  ('Ankle: Heel Walk, Toes Turned In', 'balance', 'strength', array['ankles', 'feet'], 'Walking on the heels with the toes turned in loads the muscles at the front and inside of the shin together, the inversion and dorsiflexion strength the banded drill trains, with no equipment.', 'C', array[]::text[], 2, '20m', false, false, 'Lift your toes, turn them in slightly, and walk slowly on your heels.', 'Stand tall and lift the front of both feet off the floor. Turn your toes in a little so you feel the inside of your shins working. Walk forward on your heels in short steps. Keep your knees soft and your hips level. Stop and reset if your toes touch down.'),
  ('Ankle: Two-Leg Pogo Hops', 'balance', 'plyometric', array['ankles'], 'Two-footed pogo hops train the same stiff-ankle spring as the single-leg version at half the load per ankle, the bridge between slow calf strength and single-leg hopping for an ankle with a sprain history.', 'B', array['none'], 3, '15 reps', false, false, 'Bounce on both feet in small, quick hops, landing on the balls of your feet.', 'Stand tall with your feet hip-width apart. Bounce in small, quick hops, staying on the balls of your feet. Keep your knees almost straight so the ankles do the work. Land quietly and keep the rhythm steady. Stop the set if your heels start to touch down or the hops get sloppy.'),
  ('Ankle: Single-Leg Pogo Hops', 'balance', 'plyometric', array['ankles'], 'Short, stiff-ankle hops train the calf and Achilles spring. Reactive work is the usual next step after slow heavy calf strength and is the quality the hop tests depend on.', 'B', array[]::text[], 3, '10 reps', true, false, 'Bounce on one foot in small, quick hops, landing on the ball of the foot.', 'Stand on one foot with a light touch on a wall if you need it. Bounce in small, quick hops, staying on the ball of your foot. Keep your knee almost straight so the ankle does the work. Land quietly. Stop the set if the hops get sloppy. Then switch feet.'),
  ('Ankle: Single-Leg Wall Tibialis Raise', 'balance', 'strength', array['ankles'], 'Doing the wall tibialis raise on one leg doubles the load on the muscle at the front of the shin, the progression once the two-leg version passes 20 easy reps.', 'B', array['wall'], 3, '10 reps', true, false, 'Lean on a wall with your feet out front, lift one foot, and pull the toes of the other toward your shin.', 'Lean your back on a wall with your feet about a foot and a half out. Lift one foot off the floor. Pull the toes of the standing foot up as high as you can, then lower slowly. Keep that leg straight so the movement comes from the ankle. Then switch legs.'),
  ('Ankle: Side Plank with Leg Lift', 'core', 'strength', array['hips', 'lower_back'], 'Lifting the top leg in a side plank loads the hip abductors at body weight with the trunk braced, a step up from side-lying abduction. Hip strength ranks second only to balance work in ankle-instability rehab.', 'B', array[]::text[], 3, '6 reps', true, true, 'Hold a side plank on your forearm and lift your top leg up and down slowly.', 'Lie on your side with your elbow under your shoulder and your legs stacked. Lift your hips into a straight line. Raise your top leg a foot or so, then lower it with control. Keep your hips high and facing forward. Drop to your bottom knee if you can''t hold the line. Then switch sides.'),
  ('Shoulder: Wall Slide with Lift-Off', 'pull', 'strength', array['shoulders'], 'Lifting the hands off the wall at the top of the slide makes the lower trapezius work at full elevation, the active end-range step after plain wall slides.', 'B', array['wall'], 3, '8 reps', false, true, 'Slide your forearms up the wall, then lift your hands an inch off it for 2 seconds at the top.', 'Stand facing a wall with your forearms on it at shoulder height, elbows bent. Slide your arms up as high as you can without shrugging. At the top, lift your hands an inch off the wall and hold for 2 seconds. Lower back down slowly. Keep your ribs down and don''t arch your lower back.'),
  ('Shoulder: Prone Swimmer', 'pull', 'strength', array['shoulders', 'thoracic_spine'], 'Sweeping the arms from overhead to the lower back while lying face down works the lower trapezius and rotator cuff through the whole arc, a harder bodyweight step than pull-aparts.', 'B', array[]::text[], 3, '8 reps', false, false, 'Lie face down with your arms overhead and lifted, then sweep them around to your lower back and back again.', 'Lie face down with your arms straight overhead and your forehead on a folded towel. Lift your arms off the floor. Sweep them out to the sides and down until your hands reach your lower back, turning your palms up. Reverse the path back overhead. Keep your arms off the floor the whole time and don''t lift your head.'),
  ('Shoulder: Wall-Facing Overhead Lift-Off', 'pull', 'strength', array['shoulders'], 'Holding full overhead reach with no support turns passive range from hangs and stretches into active range, which the overhead reach test needs.', 'B', array['wall'], 3, '8 reps', false, true, 'Face a wall with your hands overhead on it, then lift both hands off and hold for 2 seconds.', 'Stand facing a wall, toes a few inches from it. Slide your hands up the wall as high as they go with straight arms. Lift both hands an inch off the wall and hold for 2 seconds. Put them back and repeat. Keep your ribs down and don''t lean back to get higher.'),
  ('Shoulder: Elevated Pike Push-Up', 'push', 'strength', array['shoulders'], 'Raising the feet shifts more body weight onto the shoulders in the overhead pressing line, the standard next step after the floor pike push-up.', 'B', array['step'], 3, '6 reps', false, false, 'Put your feet on a step with your hips high, and lower your head toward the floor between your hands.', 'Place your feet on a step or low stair and walk your hands back until your hips are high and your body makes an upside-down V. Bend your elbows to lower the top of your head toward the floor. Press back up. Keep your elbows angled slightly forward, not flared out. End the set early if your form breaks.'),
  ('Shoulder: Prone 90/90 External Rotation', 'pull', 'strength', array['shoulders'], 'Rotating the forearm up against gravity with the arm at 90 degrees trains the rotator cuff in the exact position of the external rotation test, with no band.', 'B', array[]::text[], 3, '10 reps', true, true, 'Lie face down with one arm out at 90 degrees and the elbow bent, and rotate the back of your hand up toward the ceiling.', 'Lie face down on the floor or near the edge of a bed with one arm out at shoulder height and the elbow bent to 90 degrees. Keep the upper arm still and rotate the forearm so the back of your hand rises toward the ceiling. Hold for a second, then lower slowly. Don''t shrug or lift your chest. Then switch arms.'),
  ('Shoulder: Push-Up Plus', 'push', 'strength', array['shoulders'], 'The extra push at the top of a push-up is one of the strongest serratus anterior activators, and it trains the shoulder-blade control the push-up plus test checks.', 'B', array[]::text[], 3, '10 reps', false, true, 'At the top of a push-up, push the floor away so your upper back rounds slightly, then let it settle.', 'Start in a push-up position with straight arms, or on your knees if needed. Do a push-up, and at the top keep pushing the floor away until your shoulder blades spread around your ribs. Let them come back together slowly, then do the next rep. Keep your head in line with your spine and don''t let your hips sag.'),
  ('Neck: Chin Tuck Head Lift Hold', 'balance', 'strength', array['neck'], 'Lifting the tucked head just off the floor is the deep neck flexor endurance test position. Holding it is the loaded step after low-load craniocervical flexion.', 'B', array[]::text[], 3, '10s', false, true, 'Lie on your back, tuck your chin, and lift your head an inch off the floor. Hold.', 'Lie on your back with your knees bent. Tuck your chin gently as if making a double chin. Keep the tuck and lift your head about an inch off the floor. Hold for the set time, then lower and rest. Stop the hold if your chin pokes forward or your head shakes.'),
  ('Neck: Contract-Relax Rotation Stretch', 'mobility', 'mobility_stretch', array['neck'], 'Contract-relax (PNF) stretching adds range faster than static holds. A gentle 5-second push into the hand before each new end range is the active step after slow rotations.', 'B', array[]::text[], 1, '3 reps', true, false, 'Turn your head as far as is comfortable, push gently into your hand for 5 seconds, relax, then turn a little further.', 'Sit tall with your shoulders still. Turn your head to one side until you feel a gentle stretch. Place your hand on your cheek and push lightly into it for 5 seconds without moving. Relax, breathe out, and turn a little further. Hold for 10 seconds. That''s one rep. Then do the other side.'),
  ('Neck: Contract-Relax Upper Trapezius Stretch', 'mobility', 'mobility_stretch', array['neck', 'shoulders'], 'The same contract-relax method applied to the side-bend stretch. A short push against the hand before each deeper hold is the active step after plain upper trap and levator holds.', 'C', array[]::text[], 1, '3 reps', true, false, 'Tilt your ear toward your shoulder, push your head gently into your hand for 5 seconds, relax, then tilt a little further.', 'Sit tall and hold the edge of your seat with one hand to keep that shoulder down. Tilt your head away from that side. Put your other hand on the side of your head and push gently into it for 5 seconds without moving. Relax and let your head tilt a little further. Hold for 10 seconds. Then do the other side.'),
  ('Neck: Side-Lying Lateral Neck Raise', 'balance', 'strength', array['neck'], 'Lifting the head against gravity while lying on the side moves four-direction isometric work into strength through range. It belongs to the upper-quarter strengthening family with the best evidence for neck pain.', 'B', array[]::text[], 3, '8 reps', true, false, 'Lie on your side and slowly lift your head toward the ceiling, ear toward shoulder, then lower.', 'Lie on your side with a pillow or folded towel under your head. Keep your chin slightly tucked. Lift your head slowly toward the ceiling, moving your ear toward your top shoulder. Lower it back under control. Don''t turn your face up or down. Then switch sides.'),
  ('Neck: Prone Cobra with Chin Tuck', 'pull', 'strength', array['neck', 'thoracic_spine'], 'Lifting the head and chest together with the chin tucked loads the neck and upper-back extensors as one chain, the step after head-only prone extension.', 'B', array[]::text[], 3, '6 reps', false, false, 'Lie face down, tuck your chin, and lift your head and chest an inch while squeezing your shoulder blades. Hold 5 seconds.', 'Lie face down with your arms by your sides, palms down, and your forehead on the floor. Tuck your chin slightly. Lift your head and chest an inch or two while squeezing your shoulder blades back and down, and turn your thumbs out. Hold for 5 seconds, then lower. Keep your eyes on the floor and don''t tip your head back.'),
  ('Neck: Single-Arm Towel Doorway Row', 'pull', 'strength', array['shoulders', 'thoracic_spine'], 'Pulling with one arm doubles the load on each side of the upper back compared with the two-arm towel row, and adds an anti-rotation demand.', 'C', array['towel', 'doorway'], 3, '8 reps', true, false, 'Hold a towel looped on a closed door''s handle in one hand, lean back, and pull your chest to the door.', 'Loop a towel around both sides of a closed door''s handle and hold both ends in one hand. Stand with your feet near the door and lean back with a straight arm. Pull your chest toward the door, leading with the elbow, and squeeze your shoulder blade back. Lower slowly. Keep your body from twisting. Then switch arms.'),
  ('APT: Single-Leg Glute Bridge, Foot on Step', 'hinge', 'strength', array['hips', 'lower_back'], 'Putting the working heel on a step lengthens the range so the glutes work harder at full hip extension, the next step after the floor single-leg bridge.', 'B', array['step'], 3, '10 reps', true, true, 'Lie down with one heel on a low step and the other leg up, and drive your hips up.', 'Lie on your back with one heel on a low step and the knee bent. Lift the other leg straight up. Push through the heel on the step and lift your hips until your body is in a straight line. Pause for 2 seconds at the top, then lower slowly. Keep your hips level. Then switch legs.'),
  ('APT: Posterior-Tilt Plank', 'core', 'strength', array['lower_back', 'hips'], 'A front plank with the pelvis tucked under and the glutes squeezed is harder on the abdominals than a normal plank and trains the posterior tilt this sprint is after.', 'B', array[]::text[], 3, '20s', false, true, 'Hold a forearm plank, tuck your tailbone under, and squeeze your glutes and abs hard.', 'Get into a forearm plank with your elbows under your shoulders. Tuck your tailbone under so your lower back flattens. Squeeze your glutes and brace your abs hard. Pull your elbows toward your toes without moving them. Hold for the set time. Keep breathing, and stop when your lower back starts to sag.'),
  ('APT: Front-Foot-Elevated Split Squat', 'squat', 'strength', array['hips', 'knees'], 'Raising the front foot lets the back knee sink lower, which takes the rear hip into a deeper loaded stretch of the hip flexors. Loaded lengthening builds range and strength together.', 'B', array['step'], 3, '8 reps', true, false, 'Put your front foot on a step and your back foot on the floor, and sink straight down until your back knee almost touches.', 'Put your front foot on a low step and take a long stride back with the other foot. Lower straight down until your back knee nearly touches the floor. Squeeze your back glute at the bottom so you feel a stretch at the front of that hip. Push through the front foot to stand. Keep your torso tall. Then switch legs.'),
  ('APT: Bear Crawl', 'core', 'strength', array['lower_back', 'shoulders'], 'Crawling with the knees just off the floor keeps the trunk braced against movement. It is a no-equipment substitute for a loaded carry that trains anti-extension core endurance.', 'C', array[]::text[], 3, '10m', false, false, 'On your hands and toes with your knees an inch off the floor, crawl forward in small steps with a flat back.', 'Start on your hands and knees, then lift your knees an inch off the floor. Move one hand and the opposite foot forward a short step, then the other pair. Keep your back flat and your hips level, like a tray of water on your back. Go slowly. Crawl backward to return if you run out of room.'),
  ('Full Body: Bodyweight Jefferson Curl', 'hinge', 'mobility_stretch', array['hamstrings', 'lower_back'], 'A slow roll-down from a step loads the hamstrings and spine at end range with body weight only. Loaded end-range work is the step after static holds once stretch time plateaus.', 'C', array['step'], 2, '6 reps', false, false, 'Stand on a step and roll down slowly one vertebra at a time, reaching past your toes, then roll back up.', 'Stand on a step with your toes at the edge and your knees straight. Tuck your chin and roll down slowly, one segment of your spine at a time, letting your hands reach below the step. Pause at the bottom and breathe. Roll back up the same way, head last. Go slowly and stay within a gentle stretch.'),
  ('Full Body: 90/90 Back-Leg Lift-Off', 'mobility', 'mobility_stretch', array['hips'], 'Lifting the back shin off the floor from the 90/90 position works the hip rotators at end range, turning passive 90/90 range into range you can control.', 'C', array[]::text[], 2, '5 reps', true, false, 'Sit in 90/90, sit tall, and lift your back knee and foot off the floor, then lower.', 'Sit on the floor with both knees bent to about 90 degrees, one leg in front and one to the side. Sit tall with your hands on the floor beside you. Lift the back knee and foot a little off the floor, hold for 2 seconds, then lower. Keep your chest up and don''t lean away to cheat. Then switch sides.'),
  ('Full Body: Inchworm', 'mobility', 'mobility_stretch', array['hamstrings', 'shoulders', 'lower_back'], 'Walking the hands out to a plank and back stretches the hamstrings under load and moves the shoulders and trunk in one flow, a step up from standing whole-body stretches.', 'C', array[]::text[], 2, '5 reps', false, false, 'Fold down, walk your hands out to a plank, then walk your feet up to your hands.', 'Stand tall, then fold forward and put your hands on the floor, bending your knees only as much as you need. Walk your hands out until you''re in a plank. Pause, then walk your feet in toward your hands with your legs as straight as is comfortable. Stand up and repeat. Move slowly and keep your back long.'),
  ('Mobility: Quadruped Wrist Rocks', 'mobility', 'mobility_stretch', array['wrists', 'elbows'], 'Rocking body weight over the hands loads the wrists at end-range extension, the active step after unloaded wrist flows and prayer stretches.', 'C', array[]::text[], 2, '10 reps', false, false, 'On your hands and knees, rock your shoulders forward past your wrists and back with your palms flat.', 'Get on your hands and knees with your hands under your shoulders and fingers pointing forward. Keep your palms flat and rock your shoulders slowly forward past your wrists, then back. Rock only as far as is comfortable. Then turn your fingers to point back toward your knees and rock gently again.'),
  ('Knees: Single-Leg Slider Hamstring Curl', 'hinge', 'strength', array['hamstrings', 'knees'], 'Doing the slider curl on one leg roughly doubles the eccentric hamstring load, a no-equipment bridge toward Nordic-curl intensity.', 'B', array['towel'], 3, '6 reps', true, false, 'In a bridge with one heel on a towel and the other leg up, slide the heel out slowly and pull it back.', 'Lie on your back with one heel on a towel on a smooth floor and the other leg lifted. Lift your hips into a bridge. Slide the heel away slowly over 3 seconds, keeping your hips up, then pull it back in. Lower your hips to reset if you need to. Then switch legs.'),
  ('Knees: Kneeling Quad Lean-Back', 'mobility', 'mobility_stretch', array['knees', 'hips'], 'Leaning back from tall kneeling lengthens the quads under body weight, an active version of the quad stretch and a regression of the reverse Nordic.', 'C', array[]::text[], 2, '6 reps', false, false, 'Kneel tall, squeeze your glutes, and lean your whole body back a few inches, then come up.', 'Kneel on a soft surface with your knees hip-width apart and your body tall. Squeeze your glutes so your hips stay straight. Lean your whole body back a few inches in one line from knees to head, hold for 2 seconds, and come back up. Only go as far as you can control. Don''t bend at the hips.')
) as v(name, movement_pattern, exercise_type, body_parts, evidence_rationale, evidence_grade, equipment_needed, default_sets, default_rep_range, unilateral, is_corrective, cue, description)
where not exists (select 1 from exercises e where e.name = v.name and e.owner_id is null);

